using System.Security.Cryptography;
using System.Text.Json;
using UnscRelay.Core;
internal static class ErasureReceiptChecks
{
 static string Encode(byte[] bytes)=>Convert.ToBase64String(bytes).TrimEnd('=').Replace('+','-').Replace('/','_');
 public static int Run(){var count=0;void Check(bool value,string label){if(!value)throw new Exception(label);count++;Console.WriteLine("PASS erasure receipt client: "+label);}using var key=ECDsa.Create(ECCurve.NamedCurves.nistP256);var publicKey=key.ExportSubjectPublicKeyInfo();var keyId=Convert.ToHexString(SHA256.HashData(publicKey))[..32];var verifier=new ErasureReceiptVerifier(new Dictionary<string,string>{{keyId,Convert.ToBase64String(publicKey)}});var now=DateTimeOffset.UtcNow;var claims=new ErasureReceiptClaims(1,"https://unsc.responda.eu","unsc-relay-desktop-erasure",new string('A',64),"fixture-subject",Guid.NewGuid(),now.AddDays(-31).ToUnixTimeMilliseconds(),now.AddDays(-1).ToUnixTimeMilliseconds(),"completed",now.ToUnixTimeMilliseconds());ErasureReceipt Sign(ErasureReceiptClaims value){var bytes=JsonSerializer.SerializeToUtf8Bytes(value,VaultSyncCrypto.Json);return new(keyId,Encode(bytes),Encode(key.SignData(bytes,HashAlgorithmName.SHA256,DSASignatureFormat.IeeeP1363FixedFieldConcatenation)));}var receipt=Sign(claims);Check(verifier.Verify(receipt,claims.Owner,claims.Subject,now)==claims,"correct permanent receipt validates for exactly its own identity");foreach(var changed in new[]{claims with{Version=2},claims with{Issuer="https://other.invalid"},claims with{Audience="unsc-desktop"},claims with{Owner=new string('B',64)},claims with{Subject="other-subject"},claims with{RequestId=Guid.Empty},claims with{State="pending"},claims with{State="cancelled"},claims with{ExecuteAfter=now.AddDays(1).ToUnixTimeMilliseconds()},claims with{RequestedAt=claims.RequestedAt+1},claims with{IssuedAt=now.AddMinutes(2).ToUnixTimeMilliseconds()},claims with{IssuedAt=claims.ExecuteAfter-1}}){try{verifier.Verify(Sign(changed),claims.Owner,claims.Subject,now);throw new Exception("Changed receipt accepted");}catch(InvalidDataException){Check(true,"wrong identity, state, protocol or timing never authorizes destruction");}}
 foreach(var changed in new[]{receipt with{KeyId=new string('0',32)},receipt with{Payload=receipt.Payload+"!"},receipt with{Signature=Encode(new byte[64])},receipt with{Payload=new string('A',8193)}}){try{verifier.Verify(changed,claims.Owner,claims.Subject,now);throw new Exception("Forged receipt accepted");}catch(InvalidDataException){Check(true,"unknown keys, malformed or tampered receipts fail closed");}}try{new ErasureReceiptVerifier().Verify(receipt,claims.Owner,claims.Subject,now);throw new Exception("Fixture key trusted by production");}catch(InvalidDataException){Check(true,"production trust never accepts an injected fixture key");}try{verifier.Verify(receipt,claims.Owner,claims.Subject,now,Guid.NewGuid());throw new Exception("Wrong deletion request accepted");}catch(InvalidDataException){Check(true,"lookup receipt must match the exact locally persisted deletion request");}var contract=JsonDocument.Parse(File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"fixtures/erasure-receipt-contract.json"))).RootElement;var apiReceipt=contract.GetProperty("receipt").Deserialize<ErasureReceipt>(VaultSyncCrypto.Json)!;var contractVerifier=new ErasureReceiptVerifier(new Dictionary<string,string>{{apiReceipt.KeyId,contract.GetProperty("publicKey").GetString()!}});Check(contractVerifier.Verify(apiReceipt,contract.GetProperty("owner").GetString()!,contract.GetProperty("subject").GetString()!,DateTimeOffset.FromUnixTimeMilliseconds(contract.GetProperty("now").GetInt64()),contract.GetProperty("requestId").GetGuid()).RequestId==contract.GetProperty("requestId").GetGuid(),"native verifier accepts the exact API-produced signed contract bytes");Console.WriteLine("Erasure receipt client checks: "+count);return 0;}
